#!/usr/bin/env python3
"""Repo invariants: skill layout, frontmatter, links, no hardcoded SoCs, no stale references.

Errors fail the run. Warnings are printed and fail only with --strict.
"""
import re, sys, pathlib

root = pathlib.Path(__file__).resolve().parents[2]
strict = "--strict" in sys.argv
errors, warnings = [], []
rel = lambda p: p.relative_to(root)

skills = sorted(p for p in (root / "skills").iterdir() if p.is_dir())
names = {p.name for p in skills}
NOT_SKILLS = {"ti-processor-sdk-docs", "ti-sdk-env"}

# ---------------------------------------------------------------- skill layout
for d in skills:
    md = d / "SKILL.md"
    if not md.exists():
        errors.append(f"{d.name}: missing SKILL.md"); continue
    text = md.read_text()
    m = re.match(r"---\n(.*?)\n---\n", text, re.S)
    if not m:
        errors.append(f"{d.name}: no frontmatter"); continue
    fm = dict(re.findall(r"^(\w+):\s*(.*)$", m.group(1), re.M))
    if fm.get("name") != d.name:
        errors.append(f"{d.name}: frontmatter name {fm.get('name')!r} != directory")
    if not fm.get("description"):
        errors.append(f"{d.name}: missing description")
    if len(text.splitlines()) > 200:
        errors.append(f"{d.name}: SKILL.md over 200 lines")
    for sec in ("Docs (MCP)", "Prerequisites", "Verify"):
        if sec not in text:
            errors.append(f"{d.name}: missing section {sec!r}")
    for sec in ("Steps", "Troubleshooting"):
        if not re.search(rf"^##+ .*{sec}", text, re.M):
            warnings.append(f"{d.name}: no '{sec}' section (CONTRIBUTING.md)")
    if "mcp-usage.md" not in text:
        errors.append(f"{d.name}: does not link context/mcp-usage.md")
    # every scripts/ file must be referenced from SKILL.md or a reference page
    for s in (d / "scripts").glob("*") if (d / "scripts").exists() else []:
        refs = list((d / "references").glob("*.md")) if (d / "references").exists() else []
        if s.name not in text and not any(s.name in r.read_text() for r in refs):
            errors.append(f"{d.name}: unreferenced script {s.name}")

# ------------------------------------------------- docs: skill names, stale refs
top_docs = [root / f for f in ("README.md", "AGENTS.md", "CONTRIBUTING.md")]
ctx_docs = sorted((root / "context").glob("*.md"))
skill_docs = [d / "SKILL.md" for d in skills if (d / "SKILL.md").exists()]
skill_docs += [r for d in skills for r in (d / "references").glob("*.md")] if skills else []
all_docs = [p for p in top_docs + ctx_docs + skill_docs if p.exists()]

for md in all_docs:
    t = md.read_text()
    for ref in sorted(set(re.findall(r"`(ti-[a-z0-9-]+)`", t))):
        if ref not in names and ref not in NOT_SKILLS and not ref.startswith("ti-processor"):
            errors.append(f"{rel(md)}: refers to missing skill {ref}")
    if re.search(r"AM625_IOPAD|device-families", t):
        errors.append(f"{rel(md)}: stale reference")
    # the hand-written devices/ tree is gone; per-device facts are the generated KB
    for i, line in enumerate(t.splitlines(), 1):
        if re.search(r"(?<![\w/.-])devices/", line):
            errors.append(f"{rel(md)}:{i}: refers to removed devices/ tree (use $TI_KB / ti-generate-kb)")
if (root / "devices").exists():
    errors.append("devices/ must not exist (per-device facts are generated by ti-generate-kb)")

# ------------------------------------------------ every relative markdown link resolves
LINK = re.compile(r"\[[^\]]*\]\(([^)\s]+)\)")
for md in all_docs:
    for i, line in enumerate(md.read_text().splitlines(), 1):
        for target in LINK.findall(line):
            if re.match(r"^(https?:|mailto:|#)", target):
                continue
            path = target.split("#", 1)[0]
            if path and not (md.parent / path).exists():
                errors.append(f"{rel(md)}:{i}: broken link {target}")

# --------------------- skills listed in context/workflow.md exist, and vice versa
wf = root / "context" / "workflow.md"
if wf.exists():
    listed = set(re.findall(r"`(ti-[a-z0-9-]+)`", wf.read_text())) - NOT_SKILLS
    for n in sorted(listed - names):
        errors.append(f"context/workflow.md: lists skill {n} that does not exist")
    for n in sorted(names - listed):
        errors.append(f"context/workflow.md: skill {n} is not listed")
else:
    errors.append("context/workflow.md missing")

# ----------- README/AGENTS/CONTRIBUTING (and context) mention only existing paths
ROOT_PREFIX = re.compile(r"^(skills|context|lib|templates|mcp|\.github)(/|$)")
SKIP = re.compile(r"[<>$*~{}\s|]|^\.claude|^/")
all_files = {p.name for p in root.rglob("*") if p.is_file() and ".git" not in p.parts}
for md in top_docs + ctx_docs:
    if not md.exists():
        continue
    for i, line in enumerate(md.read_text().splitlines(), 1):
        for tok in re.findall(r"`([^`]+)`", line):
            if SKIP.search(tok):
                continue
            tok = tok.rstrip(",.;:")
            if ROOT_PREFIX.match(tok):
                if not (root / tok).exists():
                    errors.append(f"{rel(md)}:{i}: path {tok} does not exist")
            elif md in top_docs and "/" not in tok and re.search(r"\.(md|sh|py|ya?ml)$", tok):
                if tok not in all_files:
                    errors.append(f"{rel(md)}:{i}: file {tok} does not exist anywhere in the repo")

# ---------------------------------------------------- no hardcoded SoC names in skills
# Flags SoC/family tokens (AM62P, am62x, AM64, J721E, J722S, TDA4VM, DRA821, ...) in skills.
# A hit is allowed when its line, or an earlier line of the same paragraph/list item/table row,
# contains "example" or "e.g." (case-insensitive) or "lint:soc-ok", or when it sits in a fenced block whose opening fence is preceded by a line containing "(example".
# SKILL.md and scripts: error. references/*.md: warning (they cite evidence from a reference SDK).
SOC = re.compile(r"(?i)(?<![A-Za-z0-9_])(am6\d[a-z0-9]*|j7\d\d[a-z0-9]*|dra\d{2,}[a-z0-9]*|tda4[a-z0-9]*)(?![A-Za-z0-9])")
OK_LINE = re.compile(r"(?i)example|e\.g\.|lint:soc-ok")


def soc_hits(path):
    lines = path.read_text(errors="replace").splitlines()
    in_fence, fence_ok, prev, para_ok = False, False, "", False
    for i, line in enumerate(lines, 1):
        if line.lstrip().startswith("```"):
            if not in_fence:
                in_fence, fence_ok = True, "(example" in prev.lower()
            else:
                in_fence = False
            continue
        if in_fence:
            if fence_ok:
                continue
        else:
            # A marker covers the rest of its paragraph / list item / table row.
            if not line.strip() or re.match(r"\s*([-*|#]|\d+\.)\s", line) or line.startswith("|"):
                para_ok = False
            if line.strip():
                prev = line
        if OK_LINE.search(line):
            para_ok = True
        if para_ok:
            continue
        m = SOC.search(line)
        if m:
            yield i, m.group(1)


for d in skills:
    targets = [(d / "SKILL.md", errors)]
    targets += [(p, errors) for p in sorted((d / "scripts").glob("*")) if p.is_file()] if (d / "scripts").exists() else []
    targets += [(p, warnings) for p in sorted((d / "references").rglob("*.md"))] if (d / "references").exists() else []
    for p, sink in targets:
        if not p.exists():
            continue
        for i, tok in soc_hits(p):
            sink.append(f"{rel(p)}:{i}: hardcoded SoC name {tok!r} (parameterize, or mark the line 'example')")

# ---------------------------------------------------------------------- report
for w in warnings:
    print("warning:", w)
if errors or (strict and warnings):
    print("\n".join(errors)); sys.exit(1)
print(f"ok: {len(skills)} skills, {len(warnings)} warnings")
